require(['gram/gram'], function(gram) {

    var GramShell = gram.view.system.GramShell;
    var G = gram.view.widget.svg.G;
    var Rect = gram.view.widget.svg.Rect;
    var Svg = gram.view.widget.svg.Svg;

    var shell = new GramShell('container');

    var svg = new Svg();
    shell.contents(svg);

    svg.focusTraversable(true);
    svg.bounds(0, 0, 400, 400);

    var g = new G();
    g.cursor('move');
    g.location(100, 100);
    svg.append(g);

    var r1 = new Rect();
    r1.cursor('cell')
        .border(10, 'salmon')
        .bgColor('moccasin')
        .bounds(0, 0, 100, 100);
    g.append(r1);

    var r2 = new Rect();
    r2.cursor('cell')
        .border(10, 'salmon')
        .bgColor('moccasin')
        .bounds(100, 100, 100, 100);
    g.append(r2);

    setInterval(function () {
        var x = parseInt(Math.random()*100);
        var y = parseInt(Math.random()*100);
        g.location(x, y);
    }, 1000);

});
